/*
 * Zigbee Coordinator — Board 1
 * Receives sensor data from Zigbee End Device
 * Red LED on D2 blinks on each data receive
 */

#include <Zigbee.h>

// Sensor data structure
typedef struct {
  int sensorValue;
  float voltage;
} SensorPacket;

SensorPacket sensorData;
int packetCount = 0;

// Callback when data is received
void onDataReceived(uint8_t *data, int len) {
  memcpy(&sensorData, data, sizeof(sensorData));
  packetCount++;

  Serial.print("[Coordinator] RX #");
  Serial.print(packetCount);
  Serial.print(" | Sensor: ");
  Serial.print(sensorData.sensorValue);
  Serial.print(" (

V)");

  // Blink LED on receive
  digitalWrite(2, HIGH);
  delay(30);
  digitalWrite(2, LOW);
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  // Initialize Zigbee network
  Zigbee.begin(11, 0x1234);
  Zigbee.onReceive(onDataReceived);

  Serial.println("[Coordinator] Zigbee Sensor Network - Coordinator");
  Serial.print("[Coordinator] Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.println("[Coordinator] Waiting for sensor data...\n");
}

void loop() {
  delay(100);
}

