/*
 * Zigbee End Device (Sensor Node) — Board 2
 * Reads potentiometer on A0 and sends via Zigbee
 * Sends sensor data every 1.5 seconds
 */

#include <Zigbee.h>

// Coordinator short address
uint16_t coordinatorAddr = 0x0000;

// Sensor data structure
typedef struct {
  int sensorValue;
  float voltage;
} SensorPacket;

SensorPacket sensorData;
int sendCount = 0;

void setup() {
  Serial.begin(115200);
  pinMode(A0, INPUT);

  // Initialize Zigbee
  Zigbee.begin(11, 0x1234);

  Serial.println("[Sensor Node] Zigbee Sensor Node ready!");
  Serial.print("[Sensor Node] Address: 0x");
  Serial.println(Zigbee.getNodeAddress(), HEX);
  Serial.println("[Sensor Node] Reading potentiometer on A0...\n");
}

void loop() {
  // Read potentiometer (0-4095 for 12-bit ADC)
  int rawValue = analogRead(A0);
  float voltage = rawValue * (3.3 / 4095.0);

  sensorData.sensorValue = rawValue;
  sensorData.voltage = voltage;

  // Send to Coordinator
  Zigbee.send(coordinatorAddr, (uint8_t *)&sensorData, sizeof(sensorData));

  sendCount++;
  Serial.print("[Sensor Node] TX #");
  Serial.print(sendCount);
  Serial.print(" | Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Voltage: ");
  Serial.print(voltage);
  Serial.println("V");

  delay(1500);
}
